<script setup>import {ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';const qty=ref(''),msg=ref('');const submit=p=>{const r=actions.submitInventory(p.id,qty.value);msg.value=r.message||(r.ok?'已提交，等待管理员复核':'操作失败')}</script>
<template><section class="h5-page"><div class="h5-module-hero"><span>盘</span><h2>物资盘点</h2><p>填写现场清点数量</p></div><p v-if="msg" class="action-message">{{msg}}</p><article v-for="p in state.inventoryPlans" :key="p.id" class="h5-card"><header><strong>{{p.station}}</strong><span>{{p.status}}</span></header><p>台账数量：{{p.bookQuantity}}</p><input v-if="p.status==='待盘点'" v-model="qty" type="number" min="0" placeholder="现场数量"><button v-if="p.status==='待盘点'" class="primary-button active" @click="submit(p)">提交盘点</button><p v-else>已提交，等待管理员复核</p></article></section></template>
